public class SimulacionFisica extends Trabajo {

    private double resolucionMalla;

    public SimulacionFisica(String codigo, String estudio, String proyecto,
                           double horasEstimadas, Horario horario,
                           double resolucionMalla) {

        // Inicializa y valida los datos comunes en Trabajo.
        super(codigo, estudio, proyecto, horasEstimadas, horario);

        // Rechaza cualquier horario distinto del nocturno.
        if (horario != Horario.NOCTURNO) {
            throw new IllegalArgumentException(
                "Las simulaciones físicas solo admiten horario nocturno."
            );
        }

        // Valida que la malla esté entre 1 y 50 millones de celdas.
        if (!Double.isFinite(resolucionMalla)
                || resolucionMalla < 1
                || resolucionMalla > 50) {
            throw new IllegalArgumentException(
                "La resolución de la malla debe estar entre 1 y 50 millones de celdas."
            );
        }

        this.resolucionMalla = resolucionMalla;
    }

    // Calcula el costo de la simulación.
    @Override
    public double calcularCosto() {
        // Suma la base nocturna, Q22 por hora estimada y Q65 por GPU.
        return tarifaBase() + 22.0 * horasEstimadas + 65.0;
    }

    // Devuelve el plazo fijo de entrega en horas.
    @Override
    public int calcularTiempoEntrega() {
        // Todas las simulaciones tienen una entrega estimada de 18 horas.
        return 18;
    }

    // Permite únicamente el intento inicial, sin reintentos.
    @Override
    public int getIntentosMaximos() {
        return 1;
    }

    // Identifica la categoría para consultas y reportes.
    @Override
    public String getCategoria() {
        return "Simulación física";
    }

    // Comprueba que el nodo tenga la GPU necesaria para ejecutar la simulación.
    @Override
    public boolean esCompatibleCon(Nodo nodo) {
        // Rechaza una referencia de nodo inexistente.
        if (nodo == null) {
            throw new IllegalArgumentException(
                "Debe proporcionar un nodo."
            );
        }

        // Solo permite nodos que tengan GPU.
        return nodo.isTieneGPU();
    }

    public double getResolucionMalla() {
        return resolucionMalla;
    }
}